*** Update File: /root/local.rules
@@
-# Write your rule(s) here.
-# Requirement: raise exactly sid:1000001 for the custom exfil pattern.
+alert http any any -> any any (
+  msg:"TLM telemetry exfil pattern";
+  flow:established,to_server;
+
+  http.method; content:"POST"; nocase;
+  http.uri; pcre:"/^\\/telemetry\\/v2\\/report$/";
+  http.header; content:"X-TLM-Mode|3a| exfil"; nocase;
+
+  http_client_body; content:"blob=";
+  http_client_body; pcre:"/blob=[A-Za-z0-9+\\/=]{80,}(?:&|$)/";
+  http_client_body; content:"sig=";
+  http_client_body; pcre:"/sig=[0-9a-fA-F]{64}(?:&|$)/";
+
+  sid:1000001;
+  rev:1;
+)
*** End Patch

